import type { NextConfig } from "next";

/**
 * Static export: `npm run build` writes plain HTML/CSS/JS into the `out/` folder.
 * Cloudflare Pages serves that folder directly: no server, no cold starts, no server bill.
 */
const nextConfig: NextConfig = {
  output: "export",
  // /courses -> /courses/index.html. Works reliably on every static host.
  trailingSlash: true,
  // The default image optimiser needs a server. We pre-size images instead.
  images: { unoptimized: true },
  // Tailwind v4 loader for Turbopack (generated by create-next-app; keep it).
  turbopack: {
    rules: {
      "*.css": {
        loaders: ["@tailwindcss/turbopack"],
        as: "*.css",
      },
    },
  },
};

export default nextConfig;
